## nim2ts: generate TypeScript declarations from Nim types.
##
## Annotate a type with `{.ts.}` and every `nim c` rewrites `nim2tsOut`
## with TypeScript versions of all annotated types:
##
## ```nim
## type
##   User* {.ts.} = object
##     id*: int
##     name*: string
## ```

import std/macros
import nim2ts/convert

const nim2tsOut* {.strdefine.} = "types.ts"
  ## Where the generated file is written, relative to the directory the
  ## compiler runs in. Override with `-d:nim2tsOut=path/to/types.ts`.

const header = "// Generated by nim2ts. Do not edit by hand.\n"

var tsDecls {.compileTime.}: seq[tuple[name, code: string]]
  ## Every declaration generated so far in this compilation, across all modules.

macro ts*(typeDef: untyped): untyped =
  ## Type pragma: `type Foo {.ts.} = ...`. Nim passes us the `nnkTypeDef`,
  ## we record its TypeScript version and hand the type back unchanged.
  let decl = toTsDecl(typeDef)
  for existing in tsDecls:
    if existing.name == decl.name:
      error("nim2ts: a type named '" & decl.name &
        "' is already exported to TypeScript", typeDef)
  tsDecls.add decl

  # Rewrite the whole file each time: the last `{.ts.}` in the compilation
  # leaves the complete file behind, and removed types disappear from it.
  # (Under `nim check` and nimsuggest, `writeFile` is a no-op.)
  var content = header
  for d in tsDecls:
    content.add "\n" & d.code & "\n"
  writeFile(nim2tsOut, content)

  result = typeDef
